CREATE VIEW public.suppliers WITH (security_invoker=true) AS SELECT id, company_name, contact_person, phone, email, address FROM public.vendors;
GRANT SELECT ON public.suppliers TO authenticated, service_role;
COMMENT ON VIEW public.suppliers IS 'Read-only supplier compatibility projection; vendors remains the canonical supplier record.';
CREATE VIEW public.equipment_request_items WITH (security_invoker=true) AS SELECT id, id AS request_id, item_id, item_name, quantity, unit, description FROM public.supply_requests;
GRANT SELECT ON public.equipment_request_items TO authenticated, service_role;
COMMENT ON VIEW public.equipment_request_items IS 'Read-only line-item projection of canonical single-item supply requests; multi-item approval is not implemented. Submit through supply_requests and advance only through act_on_supply.';
CREATE TABLE public.store_receipts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receipt_number text, receipt_date date DEFAULT current_date, supplier_id uuid REFERENCES public.vendors(id), purchase_order_id uuid REFERENCES public.purchase_orders(id), item_id uuid REFERENCES public.inventory_items(id), quantity integer, unit text, received_by uuid REFERENCES public.officers(id), remarks text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.store_receipts TO authenticated;
GRANT ALL ON public.store_receipts TO service_role;
ALTER TABLE public.store_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY logistics_admin_only ON public.store_receipts FOR ALL TO authenticated USING (public.has_role(auth.uid(),'system_admin')) WITH CHECK (public.has_role(auth.uid(),'system_admin'));
CREATE TRIGGER audit_store_receipts AFTER INSERT OR UPDATE OR DELETE ON public.store_receipts FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.store_issues (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), issue_number text, issue_date date DEFAULT current_date, request_id uuid REFERENCES public.supply_requests(id), item_id uuid REFERENCES public.inventory_items(id), quantity integer, unit text, section_id uuid REFERENCES public.sections(id), issued_to uuid REFERENCES public.officers(id), issued_by uuid REFERENCES public.officers(id), remarks text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.store_issues TO authenticated;
GRANT ALL ON public.store_issues TO service_role;
ALTER TABLE public.store_issues ENABLE ROW LEVEL SECURITY;
CREATE POLICY logistics_admin_only ON public.store_issues FOR ALL TO authenticated USING (public.has_role(auth.uid(),'system_admin')) WITH CHECK (public.has_role(auth.uid(),'system_admin'));
CREATE TRIGGER audit_store_issues AFTER INSERT OR UPDATE OR DELETE ON public.store_issues FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.inventory_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid REFERENCES public.inventory_items(id), movement_type text, quantity integer, movement_date timestamptz DEFAULT now(), receipt_id uuid REFERENCES public.store_receipts(id), issue_id uuid REFERENCES public.store_issues(id), request_id uuid REFERENCES public.supply_requests(id), recorded_by uuid REFERENCES public.officers(id), remarks text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.inventory_movements TO authenticated;
GRANT ALL ON public.inventory_movements TO service_role;
ALTER TABLE public.inventory_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY logistics_admin_only ON public.inventory_movements FOR ALL TO authenticated USING (public.has_role(auth.uid(),'system_admin')) WITH CHECK (public.has_role(auth.uid(),'system_admin'));
CREATE TRIGGER audit_inventory_movements AFTER INSERT OR UPDATE OR DELETE ON public.inventory_movements FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.asset_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES public.assets(id), officer_id uuid REFERENCES public.officers(id), section_id uuid REFERENCES public.sections(id), assigned_date date DEFAULT current_date, returned_date date, assigned_by uuid REFERENCES public.officers(id), remarks text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.asset_assignments TO authenticated;
GRANT ALL ON public.asset_assignments TO service_role;
ALTER TABLE public.asset_assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY logistics_admin_only ON public.asset_assignments FOR ALL TO authenticated USING (public.has_role(auth.uid(),'system_admin')) WITH CHECK (public.has_role(auth.uid(),'system_admin'));
CREATE TRIGGER audit_asset_assignments AFTER INSERT OR UPDATE OR DELETE ON public.asset_assignments FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.asset_transfers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES public.assets(id), from_officer_id uuid REFERENCES public.officers(id), to_officer_id uuid REFERENCES public.officers(id), from_section_id uuid REFERENCES public.sections(id), to_section_id uuid REFERENCES public.sections(id), transfer_date date DEFAULT current_date, recorded_by uuid REFERENCES public.officers(id), reason text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.asset_transfers TO authenticated;
GRANT ALL ON public.asset_transfers TO service_role;
ALTER TABLE public.asset_transfers ENABLE ROW LEVEL SECURITY;
CREATE POLICY logistics_admin_only ON public.asset_transfers FOR ALL TO authenticated USING (public.has_role(auth.uid(),'system_admin')) WITH CHECK (public.has_role(auth.uid(),'system_admin'));
CREATE TRIGGER audit_asset_transfers AFTER INSERT OR UPDATE OR DELETE ON public.asset_transfers FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.asset_maintenance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES public.assets(id), maintenance_date date, maintenance_type text, description text, supplier_id uuid REFERENCES public.vendors(id), cost numeric(15,2), next_service_date date, recorded_by uuid REFERENCES public.officers(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.asset_maintenance TO authenticated;
GRANT ALL ON public.asset_maintenance TO service_role;
ALTER TABLE public.asset_maintenance ENABLE ROW LEVEL SECURITY;
CREATE POLICY logistics_admin_only ON public.asset_maintenance FOR ALL TO authenticated USING (public.has_role(auth.uid(),'system_admin')) WITH CHECK (public.has_role(auth.uid(),'system_admin'));
CREATE TRIGGER audit_asset_maintenance AFTER INSERT OR UPDATE OR DELETE ON public.asset_maintenance FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.vehicle_bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid REFERENCES public.vehicles(id), requested_by uuid REFERENCES public.officers(id), driver_id uuid REFERENCES public.officers(id), section_id uuid REFERENCES public.sections(id), start_at timestamptz, end_at timestamptz, destination text, purpose text, status text, remarks text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.vehicle_bookings TO authenticated;
GRANT ALL ON public.vehicle_bookings TO service_role;
ALTER TABLE public.vehicle_bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY logistics_admin_only ON public.vehicle_bookings FOR ALL TO authenticated USING (public.has_role(auth.uid(),'system_admin')) WITH CHECK (public.has_role(auth.uid(),'system_admin'));
CREATE TRIGGER audit_vehicle_bookings AFTER INSERT OR UPDATE OR DELETE ON public.vehicle_bookings FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.fuel_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid REFERENCES public.vehicles(id), booking_id uuid REFERENCES public.vehicle_bookings(id), fuel_date date DEFAULT current_date, fuel_type text, litres numeric(12,3), cost numeric(15,2), odometer numeric(12,2), supplier_id uuid REFERENCES public.vendors(id), recorded_by uuid REFERENCES public.officers(id), remarks text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.fuel_logs TO authenticated;
GRANT ALL ON public.fuel_logs TO service_role;
ALTER TABLE public.fuel_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY logistics_admin_only ON public.fuel_logs FOR ALL TO authenticated USING (public.has_role(auth.uid(),'system_admin')) WITH CHECK (public.has_role(auth.uid(),'system_admin'));
CREATE TRIGGER audit_fuel_logs AFTER INSERT OR UPDATE OR DELETE ON public.fuel_logs FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.maintenance_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_id uuid REFERENCES public.vehicles(id), maintenance_date date, maintenance_type text, description text, odometer numeric(12,2), cost numeric(15,2), supplier_id uuid REFERENCES public.vendors(id), next_service_date date, recorded_by uuid REFERENCES public.officers(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.maintenance_logs TO authenticated;
GRANT ALL ON public.maintenance_logs TO service_role;
ALTER TABLE public.maintenance_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY logistics_admin_only ON public.maintenance_logs FOR ALL TO authenticated USING (public.has_role(auth.uid(),'system_admin')) WITH CHECK (public.has_role(auth.uid(),'system_admin'));
CREATE TRIGGER audit_maintenance_logs AFTER INSERT OR UPDATE OR DELETE ON public.maintenance_logs FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
CREATE TABLE public.stock_reconciliation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reconciliation_number text, reconciliation_date date DEFAULT current_date, item_id uuid REFERENCES public.inventory_items(id), system_quantity integer, counted_quantity integer, variance integer GENERATED ALWAYS AS (counted_quantity - system_quantity) STORED, reason text, counted_by uuid REFERENCES public.officers(id), reviewed_by uuid REFERENCES public.officers(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.stock_reconciliation TO authenticated;
GRANT ALL ON public.stock_reconciliation TO service_role;
ALTER TABLE public.stock_reconciliation ENABLE ROW LEVEL SECURITY;
CREATE POLICY logistics_admin_only ON public.stock_reconciliation FOR ALL TO authenticated USING (public.has_role(auth.uid(),'system_admin')) WITH CHECK (public.has_role(auth.uid(),'system_admin'));
CREATE TRIGGER audit_stock_reconciliation AFTER INSERT OR UPDATE OR DELETE ON public.stock_reconciliation FOR EACH ROW EXECUTE FUNCTION public.audit_trigger();
COMMENT ON TABLE public.inventory_movements IS 'Staged logistics records only; no automatic stock mutation or capture of existing adjustments is implemented.';
COMMENT ON TABLE public.store_receipts IS 'Staged receipt records; recording a receipt does not update canonical inventory quantity.';
COMMENT ON TABLE public.store_issues IS 'Staged issue records; supply collection remains authorized and stock-decremented only by act_on_supply.';
COMMENT ON TABLE public.asset_assignments IS 'Staged assignment history; assets.assigned_to remains canonical and is not automatically changed.';
COMMENT ON TABLE public.asset_transfers IS 'Staged transfer history; assets.assigned_to remains canonical and is not automatically changed.';
COMMENT ON TABLE public.stock_reconciliation IS 'Staged stock count records; variances do not automatically update canonical inventory quantity.';
CREATE INDEX inventory_movements_item_idx ON public.inventory_movements(item_id);
CREATE INDEX store_receipts_item_idx ON public.store_receipts(item_id);
CREATE INDEX store_issues_request_idx ON public.store_issues(request_id);
CREATE INDEX asset_assignments_asset_idx ON public.asset_assignments(asset_id);
CREATE INDEX asset_transfers_asset_idx ON public.asset_transfers(asset_id);
CREATE INDEX asset_maintenance_asset_idx ON public.asset_maintenance(asset_id);
CREATE INDEX vehicle_bookings_vehicle_idx ON public.vehicle_bookings(vehicle_id);
CREATE INDEX fuel_logs_vehicle_idx ON public.fuel_logs(vehicle_id);
CREATE INDEX maintenance_logs_vehicle_idx ON public.maintenance_logs(vehicle_id);
CREATE INDEX stock_reconciliation_item_idx ON public.stock_reconciliation(item_id);